<?php

class BracketSequenceSolver {
    private $n;
    private $m;
    private $a;
    private $b;
    private $memo;

    public function __construct($n, $m, $a, $b) {
        $this->n = $n;
        $this->m = $m;
        $this->a = $a;
        $this->b = $b;
        $this->memo = [];
    }

    public function solve() {
        $totalLength = $this->n * $this->m;
        $minCost = $this->minCost(0, 0, 0, $totalLength);
        return $minCost;
    }

    private function minCost($pos, $balance, $openCount, $totalLength) {
        if ($pos === $totalLength) {
            return $balance === 0 ? 0 : PHP_INT_MAX;
        }

        $key = $pos . '|' . $balance . '|' . $openCount;
        if (isset($this->memo[$key])) {
            return $this->memo[$key];
        }

        $cost = PHP_INT_MAX;
        $maxOpen = ($totalLength - $pos + $balance) / 2;
        $maxOpen = min($maxOpen, $this->m * $this->n / 2 - $openCount);

        for ($i = 0; $i <= $maxOpen; $i++) {
            $nextPos = $pos + $i + 1;
            if ($nextPos > $totalLength) {
                break;
            }

            $nextBalance = $balance + $i - 1;
            if ($nextBalance < 0) {
                continue;
            }

            $nextOpenCount = $openCount + $i;
            if ($nextOpenCount > $this->m * $this->n / 2) {
                continue;
            }

            $segmentCost = 0;
            for ($j = 0; $j < $i; $j++) {
                $segmentCost += $this->a[($pos + $j) % $this->n];
            }
            $segmentCost += $this->b[($pos + $i) % $this->n];

            $remainingCost = $this->minCost($nextPos, $nextBalance, $nextOpenCount, $totalLength);
            if ($remainingCost !== PHP_INT_MAX) {
                $cost = min($cost, $segmentCost + $remainingCost);
            }
        }

        $this->memo[$key] = $cost;
        return $cost;
    }
}

