<?php

function main() {
    $line = trim(fgets(STDIN));
    list($n, $m) = array_map('intval', explode(' ', $line));
    $a = array_map('intval', explode(' ', trim(fgets(STDIN))));
    $b = array_map('intval', explode(' ', trim(fgets(STDIN))));

    // Precompute the cost for each position in the cycle
    $cost = [];
    for ($i = 0; $i < $n; $i++) {
        $cost[$i] = [$a[$i], $b[$i]];
    }

    // DP state: dp[balance] = min cost
    // balance can be from 0 to n (since we process n positions per cycle)
    // We use an array where index is balance, value is min cost
    $INF = PHP_INT_MAX;
    $dp = array_fill(0, $n + 1, $INF);
    $dp[0] = 0;

    // Process one cycle of n positions
    for ($i = 0; $i < $n; $i++) {
        $new_dp = array_fill(0, $n + 1, $INF);
        for ($bal = 0; $bal <= $n; $bal++) {
            if ($dp[$bal] === $INF) continue;
            // Option 1: place '('
            if ($bal + 1 <= $n) {
                $new_cost = $dp[$bal] + $cost[$i][0];
                if ($new_cost < $new_dp[$bal + 1]) {
                    $new_dp[$bal + 1] = $new_cost;
                }
            }
            // Option 2: place ')'
            if ($bal > 0) {
                $new_cost = $dp[$bal] + $cost[$i][1];
                if ($new_cost < $new_dp[$bal - 1]) {
                    $new_dp[$bal - 1] = $new_cost;
                }
            }
        }
        $dp = $new_dp;
    }

    // After processing one cycle, dp[0] should be the min cost for one cycle
    // that starts and ends with balance 0
    $cycle_cost = $dp[0];

    // Total cost is cycle_cost * m
    echo $cycle_cost * $m . "\n";
}

main();
