    // balance can be 0..n (since max balance is n for a regular sequence of nm brackets)
    $INF = PHP_INT_MAX;
    $dp = array_fill(0, $n + 1, array_fill(0, $n, $INF));
    $dp[0][0] = 0;

    $total = $n * $m;
