        $mod = $i % $n;
        $new_dp = array_fill(0, $n + 1, array_fill(0, $n, $INF));
        for ($bal = 0; $bal <= $n; $bal++) {
            for ($prev_mod = 0; $prev_mod < $n; $prev_mod++) {
                if ($dp[$bal][$prev_mod] === $INF) continue;
                $current_cost = $dp[$bal][$prev_mod];

                // Place '('
                $new_bal = $bal + 1;
                if ($new_bal <= $n) {
                    $new_mod = ($prev_mod + 1) % $n;
                    $add_cost = $cost[$mod][0];
                    if ($current_cost + $add_cost < $new_dp[$new_bal][$new_mod]) {
                        $new_dp[$new_bal][$new_mod] = $current_cost + $add_cost;
                    }
                }

                // Place ')'
                if ($bal > 0) {
                    $new_bal = $bal - 1;
                    $new_mod = ($prev_mod + 1) % $n;
                    $add_cost = $cost[$mod][1];
                    if ($current_cost + $add_cost < $new_dp[$new_bal][$new_mod]) {
                        $new_dp[$new_bal][$new_mod] = $current_cost + $add_cost;
                    }
                }
            }
        }
        $dp = $new_dp;
    }

    $ans = $dp[0][0];
    echo $ans . "\n";
}

main();
