$INF = PHP_INT_MAX;

function main() {
    global $n, $max_mask, $INF;
    $line = trim(fgets(STDIN));
    list($n, $m) = array_map('intval', explode(' ', $line));
    $a = array_map('intval', explode(' ', trim(fgets(STDIN))));
    $b = array_map('intval', explode(' ', trim(fgets(STDIN))));

    $max_mask = 1 << $n;
    $dp = array_fill(0, $max_mask, $INF);
    $dp[0] = 0;

    for ($i = 0; $i < $n * $m; $i++) {
        $new_dp = array_fill(0, $max_mask, $INF);
        $mod = $i % $n;
        for ($mask = 0; $mask < $max_mask; $mask++) {
            if ($dp[$mask] === $INF) continue;
            $cnt = substr_count($mask, '1');
            if ($cnt < $n) {
                $new_mask = $mask | (1 << $cnt);
                $cost = $dp[$mask] + $a[$mod];
                if ($cost < $new_dp[$new_mask]) $new_dp[$new_mask] = $cost;
            }
            if ($cnt > 0) {
                $new_mask = $mask & ~(1 << ($cnt - 1));
                $cost = $dp[$mask] + $b[$mod];
                if ($cost < $new_dp[$new_mask]) $new_dp[$new_mask] = $cost;
            }
        }
        $dp = $new_dp;
    }
    echo $dp[0] . "\n";
}
main();
