<?php

class BracketSequenceSolver {
    private $n;
    private $m;
    private $a;
    private $b;
    private $memo;

    public function __construct($n, $m, $a, $b) {
        $this->n = $n;
        $this->m = $m;
        $this->a = $a;
        $this->b = $b;
        $this->memo = [];
    }

    public function solve() {
        $totalLength = $this->n * $this->m;
        $balance = 0;
        $ink = 0;
        $openCount = 0;
        $closeCount = 0;

        for ($i = 0; $i < $totalLength; $i++) {
            $mod = $i % $this->n;
            if ($balance == 0) {
                $ink += $this->a[$mod];
                $balance++;
                $openCount++;
            } else {
                $ink += $this->b[$mod];
                $balance--;
                $closeCount++;
            }
        }

        return $ink;
    }
}

function main() {
    $input = trim(file_get_contents("php://stdin"));
    $lines = explode("\n", $input);

    $firstLine = explode(" ", trim($lines[0]));
    $n = intval($firstLine[0]);
    $m = intval($firstLine[1]);

    $a = array_map('intval', explode(" ", trim($lines[1])));
    $b = array_map('intval', explode(" ", trim($lines[2])));

    $solver = new BracketSequenceSolver($n, $m, $a, $b);
    echo $solver->solve() . "\n";
}

